/*! bridgey site samples (build 時に site.js と views から生成) */
window.__BRIDGEY_SAMPLES = {"homeDemo":{"js":"const UNIT_PRICE = 1100;\r\n    const quantity = $$.state(1);\r\n\r\n    const total = $$.computed(() => quantity() * UNIT_PRICE);\r\n\r\n    $el.find(\"@qty\").text(quantity);\r\n    $el.find(\"@total\").text(total, $$.money);\r\n\r\n    $el.find(\"@inc\").click(() => quantity((current) => current + 1));\r\n    $el.find(\"@dec\").click(() => quantity((current) => Math.max(1, current - 1)));\r\n\r\n    $el.find(\"@free\").when(() => quantity() >= 3);\r\n    $el.find(\"@bar\").vars({\r\n      progress: () => `${Math.min(100, quantity() * 20)}%`,\r\n    });\r\n  }\r\n\r\n  $$.component(\"home-demo\", ($el) => {\r\n    homeDemo($el);\r\n    showSample(\"home-demo-source\", \"homeDemo\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // シンタックスハイライト。\r\n  //\r\n  // 外部ライブラリは入れない（依存ゼロの看板と、CSPセーフを保つため）。\r\n  // 既に .tok-* が手で書かれている <pre> は触らない。\r\n  // ---------------------------------------------------------------------------\r\n  const TOKENS = new RegExp(\r\n    [\r\n      \"(?<c>//[^\\\\n]*|/\\\\*[\\\\s\\\\S]*?\\\\*/|<!--[\\\\s\\\\S]*?-->)\", // コメント\r\n      \"(?<s>\\\"(?:[^\\\"\\\\\\\\]|\\\\\\\\.)*\\\"|'(?:[^'\\\\\\\\]|\\\\\\\\.)*'|`(?:[^`\\\\\\\\]|\\\\\\\\.)*`)\", // 文字列\r\n      \"(?<t></?[a-zA-Z][\\\\w-]*)\", // HTML タグ\r\n      \"(?<k>\\\\b(?:const|let|var|function|return|if|else|for|of|in|await|async|new|\" +\r\n        \"import|export|from|class|extends|try|catch|finally|throw|typeof|\" +\r\n        \"true|false|null|undefined|this)\\\\b)\", // キーワード\r\n      \"(?<f>\\\\b[A-Za-z_$][\\\\w$]*(?=\\\\s*\\\\())\", // 呼び出し\r\n    ].join(\"|\"),\r\n    \"g\"\r\n  );\r\n\r\n  const escapeHtml = (text) =>\r\n    text.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\");\r\n\r\n  function highlight(source) {\r\n    let out = \"\";\r\n    let last = 0;\r\n    let match;\r\n    TOKENS.lastIndex = 0;\r\n    while ((match = TOKENS.exec(source))) {\r\n      out += escapeHtml(source.slice(last, match.index));\r\n      const g = match.groups;\r\n      const cls = g.c ? \"tok-c\" : g.s ? \"tok-s\" : g.t ? \"tok-t\" : g.k ? \"tok-k\" : \"tok-f\";\r\n      out += `<span class=\"${cls}\">${escapeHtml(match[0])}</span>`;\r\n      last = match.index + match[0].length;\r\n    }\r\n    return out + escapeHtml(source.slice(last));\r\n  }\r\n\r\n  /**\r\n   * コードブロックにコピーボタンを付ける。\r\n   * コピー自体は $(document) に張った .copy のハンドラが処理する。\r\n   */\r\n  function addCopyButtons(root) {\r\n    (root || document).querySelectorAll(\"pre\").forEach((pre) => {\r\n      if (pre.querySelector(\".copy-code\")) return;\r\n\r\n      const code = pre.querySelector(\"code\");\r\n      if (!code) return;\r\n\r\n      const button = document.createElement(\"button\");\r\n      button.type = \"button\";\r\n      button.className = \"copy copy-code\";\r\n      button.dataset.copy = code.textContent;\r\n      button.textContent = \"copy\";\r\n\r\n      pre.classList.add(\"has-copy\");\r\n      pre.appendChild(button);\r\n    });\r\n  }\r\n\r\n  /** そのビューの中の、まだ色が付いていないコードブロックを着色する。 */\r\n  function highlightAll(root) {\r\n    (root || document).querySelectorAll(\"pre > code\").forEach((code) => {\r\n      if (code.children.length) return; // 手で .tok-* が書かれている → 触らない\r\n      code.innerHTML = highlight(code.textContent);\r\n    });\r\n  }\r\n\r\n  /**\r\n   * コードブロックを1行ずつ <span class=\"line\"> で包む。番号は CSS のカウンタが振る。\r\n   *\r\n   * 文字列を改行で split すると、複数行にまたがるトークン（ブロックコメントや\r\n   * テンプレートリテラル）の <span> が壊れる。なので DOM を辿って切り、\r\n   * またいだ要素は行ごとに同じタグで包み直す。\r\n   *\r\n   * 番号は ::before で出すので、コピーした文字列には入らない。\r\n   */\r\n  function splitLines(node) {\r\n    const lines = [document.createDocumentFragment()];\r\n    const last = () => lines[lines.length - 1];\r\n\r\n    node.childNodes.forEach((child) => {\r\n      if (child.nodeType === 3) {\r\n        child.textContent.split(\"\\n\").forEach((part, i) => {\r\n          if (i) lines.push(document.createDocumentFragment());\r\n          if (part) last().appendChild(document.createTextNode(part));\r\n        });\r\n        return;\r\n      }\r\n      if (child.nodeType !== 1) return;\r\n\r\n      splitLines(child).forEach((fragment, i) => {\r\n        if (i) lines.push(document.createDocumentFragment());\r\n        const clone = child.cloneNode(false);\r\n        clone.appendChild(fragment);\r\n        last().appendChild(clone);\r\n      });\r\n    });\r\n\r\n    return lines;\r\n  }\r\n\r\n  function addLineNumbers(root) {\r\n    (root || document).querySelectorAll(\"pre > code\").forEach((code) => {\r\n      if (code.dataset.numbered) return;\r\n      code.dataset.numbered = \"1\";\r\n\r\n      const lines = splitLines(code);\r\n      // 末尾の改行で生まれる空行は数に入れない\r\n      while (lines.length > 1 && !lines[lines.length - 1].textContent) lines.pop();\r\n      if (lines.length < 2) return; // 1行だけなら番号は邪魔\r\n\r\n      code.textContent = \"\";\r\n      lines.forEach((fragment) => {\r\n        const line = document.createElement(\"span\");\r\n        line.className = \"line\";\r\n        line.appendChild(fragment);\r\n        code.appendChild(line);\r\n      });\r\n      code.parentElement.classList.add(\"has-lines\");\r\n    });\r\n  }\r\n\r\n  /**\r\n   * サンプルを [HTML] [jQuery] [bridgey] のタブで表示する。\r\n   *\r\n   * ラベルは「JavaScript」ではなく「bridgey」。どちらも JavaScript なので、\r\n   * 言語名では何も言っていない。読む人が知りたいのは jQuery か bridgey か。\r\n   *\r\n   * jQuery 版は書き比べたい場所にだけ置く。同じ場所に\r\n   *   <template data-brg=\"{target}-jquery\"><pre><code>…</code></pre></template>\r\n   * を書いておくと、この1列に混ざる。\r\n   * （タブの中にタブを作らない。読む人が2回選ばされることになるので）\r\n   *\r\n   * bridgey 側の中身は build 時に **元のソースから** 抜き出したもの（dist/samples.js）。\r\n   * バンドル後のコードを見せると変数名が変わって読めないので、そうしている。\r\n   * JS だけでは何を操作しているのか分からないため、HTML も見られるようにしている。\r\n   *\r\n   * このタブ自体も bridgey の state で動いている。\r\n   */\r\n  function showSample(target, name) {\r\n    const container = document.querySelector(`[data-brg=\"${target}\"]`);\r\n    if (!container) return;\r\n\r\n    const sample = (window.__BRIDGEY_SAMPLES || {})[name];\r\n    if (!sample) {\r\n      container.textContent = \"（サンプルを読み込めませんでした。npm run build を実行してください）\";\r\n      return;\r\n    }\r\n\r\n    const jqueryTemplate = document.querySelector(`template[data-brg=\"${target}-jquery\"]`);\r\n    const jqueryCode = jqueryTemplate?.content.querySelector(\"code\")?.textContent ?? \"\";\r\n\r\n    const tabs = [];\r\n    if (sample.html) tabs.push({ id: \"html\", label: \"HTML\", code: sample.html });\r\n    if (jqueryCode) tabs.push({ id: \"jquery\", label: \"jQuery\", code: jqueryCode.trim() });\r\n    tabs.push({ id: \"js\", label: \"bridgey\", code: sample.js });\r\n\r\n    // 1枚しかないなら、タブは出さない（押しても何も起きないボタンを置かない）\r\n    const tabBar =\r\n      tabs.length < 2\r\n        ? \"\"\r\n        : `<div class=\"code-tabs\">` +\r\n          tabs\r\n            .map((tab) => `<button type=\"button\" data-tab=\"${tab.id}\">${tab.label}</button>`)\r\n            .join(\"\") +\r\n          `</div>`;\r\n\r\n    container.innerHTML =\r\n      tabBar +\r\n      tabs\r\n        .map(\r\n          (tab) =>\r\n            `<div data-pane=\"${tab.id}\"><pre><code>${highlight(tab.code)}</code></pre></div>`\r\n        )\r\n        .join(\"\");\r\n\r\n    addLineNumbers(container);\r\n\r\n    const current = $$.state(tabs[0].id);\r\n\r\n    $$(container)\r\n      .find(\"[data-tab]\")\r\n      .each((tab) => {\r\n        $$(tab)\r\n          .click(() => current(tab.dataset.tab))\r\n          .selected(() => current() === tab.dataset.tab);\r\n      });\r\n\r\n    $$(container)\r\n      .find(\"[data-pane]\")\r\n      .each((pane) => {\r\n        $$(pane).when(() => current() === pane.dataset.pane);\r\n      });\r\n  }\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: 複雑な申し込みフォーム。\r\n  // 下のコード欄には、この関数の中身をそのまま表示する（手書きの写しにしない）。\r\n  // ---------------------------------------------------------------------------\r\n  const OPTIONS = [\r\n    { id: \"warranty\", name: \"延長保証（3年）\", price: 1100 },\r\n    { id: \"support\", name: \"電話サポート\", price: 550 },\r\n    { id: \"setup\", name: \"設置・組み立て\", price: 3300 },\r\n  ];\r\n\r\n  function exampleForm($el) {\r\n    const options = $$.state(OPTIONS.slice());\r\n    const plan = $el.find(\"@plan\").group();\r\n\r\n    // オプション一覧（行の DOM は使い回されるのでチェックが消えない）\r\n    $el.find(\"@opts\").repeat(options, {\r\n      key: (option) => option.id,\r\n      tpl: \"@opt-tpl\",\r\n      render: ($row, option) => {\r\n        $row.find(\"@opt-name\").text(option.name);\r\n        $row.find(\"@opt-price\").text(option.price, $$.money, \"円/月\");\r\n        $row.find(\"@opt-check\").attr(\"value\", option.id);\r\n      },\r\n    });\r\n\r\n    // 選択を1つの state にして、合計は導出する（代入する場所を作らない）\r\n    // 後からオプションが増えても、この state に自動で参加する（張り直しは要らない）\r\n    const selectedIds = $el.find(\"@opt-check\").group();\r\n\r\n    const optionTotal = $$.computed(() => {\r\n      const priceOf = new Map(options().map((option) => [option.id, option.price]));\r\n\r\n      return selectedIds().reduce((sum, id) => sum + (priceOf.get(id) ?? 0), 0);\r\n    });\r\n\r\n    $el.find(\"@opt-total\").text(optionTotal, $$.money);\r\n\r\n    // 法人のときだけ会社名を表示し、同じ条件で必須にする\r\n    const isCorporate = $$.computed(() => plan() === \"corp\");\r\n    $el.find(\"@corp-box\").when(isCorporate);\r\n\r\n    const signupForm = $el.find(\"@form\").form({\r\n      company: {\r\n        required: isCorporate,\r\n        message: \"会社名を入力してください\",\r\n      },\r\n      tel: {\r\n        pattern: /^0\\d{9,10}$/,\r\n        message: \"電話番号の形式が正しくありません（ハイフンなし）\",\r\n      },\r\n      confirm: {\r\n        same: \"password\",\r\n        message: \"パスワードが一致しません\",\r\n      },\r\n      agree: {\r\n        required: true,\r\n        message: \"規約への同意が必要です\",\r\n      },\r\n      // promo は required だが画面に出ていない → 検証されない（CV を守る）\r\n    });\r\n\r\n    // 郵便番号の自動整形（日本語変換中は書き戻さないので変換が壊れない）\r\n    const zipCode = $el.find(\"#ex-zip\").state(\"\");\r\n\r\n    $el.find(\"#ex-zip\").val(() => {\r\n      const digits = String(zipCode()).replace(/[^0-9]/g, \"\").slice(0, 7);\r\n\r\n      return digits.length > 3\r\n        ? `${digits.slice(0, 3)}-${digits.slice(3)}`\r\n        : digits;\r\n    });\r\n\r\n    $el.find(\"@err-summary\").text(signupForm.errorCount, (count) => {\r\n      return count ? `未入力・不備が${count}件あります` : \"\";\r\n    });\r\n    $el.find(\"@submit\").disabled(signupForm.submitting);\r\n    $el.find(\"@done\").when(() => {\r\n      return signupForm.submitted() && signupForm.valid() && !signupForm.submitting();\r\n    });\r\n\r\n    return { form: signupForm, options };\r\n  }\r\n\r\n  $$.component(\"ex-form\", ($el) => {\r\n    const api = exampleForm($el);\r\n    showSample(\"ex-source\", \"exampleForm\");\r\n\r\n    api.form.submit(async () => {\r\n      // 送信の代わりに待つだけ。待っている間は submit ボタンが自動で無効になる\r\n      await new Promise((r) => setTimeout(r, 900));\r\n    });\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: 構造依存の事故を、その場で起こしてみせる。\r\n  //\r\n  // 左は「隣の要素を掴む」書き方（jQuery の .next() 相当）。\r\n  // 右は「名前で引く」書き方。HTML を1段ラップすると、左だけが黙って動かなくなる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"ex-structure\", ($el) => {\r\n    // 従来のやり方: nextElementSibling で隣を掴む\r\n    const oldHead = $el.find(\"@old-head\").el;\r\n\r\n    $$(oldHead).click(() => {\r\n      const body = oldHead.nextElementSibling;\r\n\r\n      if (!body || body.dataset.brg !== \"old-body\") {\r\n        // ここが事故。掴めていないのに例外は出ないので、誰も気づけない\r\n        $el.find(\"@old-log\").text(\"開きません。隣に別の要素が入りました（例外は出ません）\");\r\n        return;\r\n      }\r\n      const hidden = body.style.display === \"none\";\r\n      body.style.display = hidden ? \"\" : \"none\";\r\n      $el.find(\"@old-log\").text(hidden ? \"開きました\" : \"閉じました\");\r\n    });\r\n\r\n    // bridgey: 名前で引くので、構造が変わっても同じ要素に届く\r\n    const open = $$.state(true);\r\n\r\n    $el.find(\"@new-head\").click(() => open((v) => !v)).expanded(open);\r\n    $el.find(\"@new-body\").when(open);\r\n    $el.find(\"@new-log\").text(open, (v) => (v ? \"開きました\" : \"閉じました\"));\r\n\r\n    $el.find(\"@wrap\").click(function () {\r\n      for (const name of [\"old-body\", \"new-body\"]) {\r\n        const target = $el.find(`@${name}`).el;\r\n        if (!target || target.parentElement.dataset.wrapper) continue;\r\n\r\n        const wrapper = document.createElement(\"div\");\r\n        wrapper.dataset.wrapper = \"1\";\r\n        target.parentElement.insertBefore(wrapper, target);\r\n        wrapper.appendChild(target);\r\n      }\r\n      this.disabled = true;\r\n      $el.find(\"@old-log\").text(\"1段ラップしました。開いてみてください。\");\r\n      $el.find(\"@new-log\").text(\"1段ラップしました。開いてみてください。\");\r\n    });\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: エラーの隔離。\r\n  // わざと初期化に失敗する部品を混ぜても、他の部品は動き続ける。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"ex-broken\", () => {\r\n    // 元コードの s.offset().top と同じ状況（存在しない要素を触る）\r\n    const missing = document.querySelector(\"#this-element-does-not-exist\");\r\n    return void missing.getBoundingClientRect();\r\n  });\r\n\r\n  $$.component(\"ex-tabs\", ($el) => {\r\n    const current = $$.state(\"a\");\r\n\r\n    $el.find(\"@tab\").each((tab) => {\r\n      $$(tab).click(() => current(tab.dataset.tab)).selected(() => current() === tab.dataset.tab);\r\n    });\r\n    $el.find(\"@pane\").each((pane) => {\r\n      $$(pane).when(() => current() === pane.dataset.tab);\r\n    });\r\n  });\r\n\r\n  $$.component(\"ex-mini\", ($el) => {\r\n    const n = $$.state(5);\r\n\r\n    $el.find(\"@mini-n\").text(n);\r\n    $el.find(\"@mini-inc\").click(() => n((v) => v + 1));\r\n    $el.find(\"@mini-dec\").click(() => n((v) => v - 1));\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: CSS に無いクラス名を検出する。\r\n  // 警告の出口（$$.warnSink）を一時的に借りて、出た文を画面にも見せる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"ex-typo\", ($el) => {\r\n    $el.find(\"@run\").click(function () {\r\n      const original = $$.warnSink;\r\n      let captured = \"\";\r\n\r\n      $$.warnSink = (message) => {\r\n        captured += (captured ? \"\\n\\n\" : \"\") + message;\r\n        original(message);\r\n      };\r\n      try {\r\n        // \".ex-active\" のつもりで綴りを間違えている\r\n        $el.find(\"@run\").toggleClass(\"ex-actve\", $$.state(true));\r\n      } finally {\r\n        $$.warnSink = original;\r\n      }\r\n\r\n      this.disabled = true;\r\n      $el.find(\"@typo-log\").text(\r\n        captured || \"（この警告は1度だけ出ます。ページを読み込み直すとまた出ます）\"\r\n      );\r\n    });\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: カート。金額を全部「導出」する例。\r\n  // 代入している行が1つもないので、数量変更・削除・クーポンで合計がズレようがない。\r\n  // ---------------------------------------------------------------------------\r\n  const CART_ITEMS = [\r\n    { id: \"desk\", name: \"昇降デスク\", unit: 23800, qty: 1 },\r\n    { id: \"arm\", name: \"モニターアーム\", unit: 3300, qty: 1 },\r\n    { id: \"cable\", name: \"USB-C ケーブル\", unit: 1650, qty: 2 },\r\n  ];\r\n\r\n  function cart($el) {\r\n    const FREE_SHIPPING_FROM = 30000;\r\n    const SHIPPING_FEE = 550;\r\n    const TAX_RATE = 0.1;\r\n    const COUPON_RATE = 0.1;\r\n\r\n    const items = $$.state(CART_ITEMS.map((item) => ({ ...item })));\r\n    const useCoupon = $el.find(\"@coupon\").state(false);\r\n\r\n    // ここから下は全部「導出」。金額に代入している行は1つもない\r\n    const subtotal = $$.computed(() => {\r\n      return items().reduce((sum, item) => sum + item.unit * item.qty, 0);\r\n    });\r\n\r\n    const shipping = $$.computed(() => {\r\n      if (subtotal() === 0) return 0;\r\n\r\n      return subtotal() >= FREE_SHIPPING_FROM ? 0 : SHIPPING_FEE;\r\n    });\r\n\r\n    const discount = $$.computed(() => {\r\n      return useCoupon() ? Math.floor(subtotal() * COUPON_RATE) : 0;\r\n    });\r\n\r\n    const taxable = $$.computed(() => subtotal() - discount() + shipping());\r\n    const tax = $$.computed(() => Math.floor(taxable() * TAX_RATE));\r\n    const total = $$.computed(() => taxable() + tax());\r\n    const amountToFreeShipping = $$.computed(() => {\r\n      return Math.max(0, FREE_SHIPPING_FROM - subtotal());\r\n    });\r\n\r\n    const changeQuantity = (id, change) => {\r\n      items((list) =>\r\n        list.map((item) => {\r\n          if (item.id !== id) return item;\r\n\r\n          return { ...item, qty: Math.max(1, change(item.qty)) };\r\n        })\r\n      );\r\n    };\r\n\r\n    const removeItem = (id) => {\r\n      items((list) => list.filter((item) => item.id !== id));\r\n    };\r\n\r\n    $el.find(\"@rows\").repeat(items, {\r\n      key: (item) => item.id,\r\n      tpl: \"@row-tpl\",\r\n      render: ($row, item) => {\r\n        $row.find(\"@name\").text(item.name);\r\n        $row.find(\"@unit\").text(item.unit, $$.money, \"円\");\r\n        $row.find(\"@qty\").text(item.qty);\r\n        $row.find(\"@line\").text(item.unit * item.qty, $$.money, \"円\");\r\n\r\n        $row.find(\"@inc\").click(() => changeQuantity(item.id, (qty) => qty + 1));\r\n        $row.find(\"@dec\").click(() => changeQuantity(item.id, (qty) => qty - 1));\r\n        $row.find(\"@del\").click(() => removeItem(item.id));\r\n      },\r\n    });\r\n\r\n    const isEmpty = $$.computed(() => items().length === 0);\r\n\r\n    $el.find(\"@empty\").when(isEmpty);\r\n    $el.find(\"@summary\").when(() => !isEmpty());\r\n    $el.find(\"@subtotal\").text(subtotal, $$.money, \"円\");\r\n    $el.find(\"@ship\").text(shipping, (fee) => {\r\n      return fee === 0 ? \"無料\" : `${$$.money(fee)}円`;\r\n    });\r\n    $el.find(\"@discount\").text(discount, (amount) => {\r\n      return amount === 0 ? \"—\" : `-${$$.money(amount)}円`;\r\n    });\r\n    $el.find(\"@tax\").text(tax, $$.money, \"円\");\r\n    $el.find(\"@total\").text(total, $$.money);\r\n    $el.find(\"@to-free\").text(amountToFreeShipping, $$.money);\r\n    $el.find(\"@free-note\").when(() => {\r\n      return amountToFreeShipping() > 0 && !isEmpty();\r\n    });\r\n\r\n    $el.find(\"@restore\").click(() => {\r\n      items(CART_ITEMS.map((item) => ({ ...item })));\r\n    });\r\n  }\r\n\r\n  $$.component(\"ex-cart\", ($el) => {\r\n    cart($el);\r\n    showSample(\"cart-source\", \"cart\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: カウンター（最小の状態管理）\r\n  // 状態は n ひとつ。表示は全部そこから導出する。\r\n  // ---------------------------------------------------------------------------\r\n  function counter($el) {\r\n    const MAX_QUANTITY = 20;\r\n    const UNIT_PRICE = 1100;\r\n\r\n    // 状態はこの1つだけ\r\n    const quantity = $$.state(1);\r\n\r\n    // ここから下は全部「導出」。どこにも代入していない\r\n    const doubled = $$.computed(() => quantity() * 2);\r\n    const total = $$.computed(() => quantity() * UNIT_PRICE);\r\n    const isBulk = $$.computed(() => quantity() >= 10);\r\n    const isMax = $$.computed(() => quantity() >= MAX_QUANTITY);\r\n\r\n    $el.find(\"@cnt-n\").text(quantity);\r\n    $el.find(\"@cnt-doubled\").text(doubled);\r\n    $el.find(\"@cnt-total\").text(total, $$.money);\r\n\r\n    $el.find(\"@cnt-inc\").click(() => {\r\n      quantity((current) => Math.min(MAX_QUANTITY, current + 1));\r\n    });\r\n    $el.find(\"@cnt-dec\").click(() => {\r\n      quantity((current) => Math.max(1, current - 1));\r\n    });\r\n    $el.find(\"@cnt-reset\").click(() => quantity(1));\r\n\r\n    $el.find(\"@cnt-inc\").disabled(isMax);\r\n    $el.find(\"@cnt-dec\").disabled(() => quantity() <= 1);\r\n    $el.find(\"@cnt-over\").when(isBulk);\r\n    $el.find(\"@cnt-limit\").when(isMax);\r\n  }\r\n\r\n  $$.component(\"ex-counter\", ($el) => {\r\n    counter($el);\r\n    showSample(\"counter-source\", \"counter\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: ToDo（一覧の状態管理）\r\n  // 一覧は repeat が描くので、行の DOM が使い回される＝入力途中の文字が消えない。\r\n  // ---------------------------------------------------------------------------\r\n  function todo($el) {\r\n    let nextId = 3;\r\n\r\n    const todos = $$.state([\r\n      { id: 1, title: \"見積書を送る\", done: false },\r\n      { id: 2, title: \"請求書を確認する\", done: true },\r\n    ]);\r\n\r\n    const filter = $el.find(\"@filter\").group();\r\n    const draft = $el.find(\"@input\").state(\"\");\r\n\r\n    // 表示する一覧は「絞り込んだ結果」を導出する\r\n    const visibleTodos = $$.computed(() => {\r\n      if (filter() === \"open\") return todos().filter((todo) => !todo.done);\r\n      if (filter() === \"done\") return todos().filter((todo) => todo.done);\r\n\r\n      return todos();\r\n    });\r\n\r\n    const remainingCount = $$.computed(() => {\r\n      return todos().filter((todo) => !todo.done).length;\r\n    });\r\n\r\n    const addTodo = () => {\r\n      const title = draft().trim();\r\n      if (!title) return;\r\n\r\n      todos((list) => [...list, { id: nextId++, title, done: false }]);\r\n      draft(\"\");\r\n    };\r\n\r\n    const setDone = (id, done) => {\r\n      todos((list) =>\r\n        list.map((todo) => {\r\n          if (todo.id !== id) return todo;\r\n\r\n          return { ...todo, done };\r\n        })\r\n      );\r\n    };\r\n\r\n    $el.find(\"@add\").click(addTodo);\r\n    $el.find(\"@input\").on(\"keydown\", (event) => {\r\n      if (event.key !== \"Enter\") return;\r\n\r\n      event.preventDefault();\r\n      addTodo();\r\n    });\r\n\r\n    $el.find(\"@counts\").text(remainingCount, \"件が未完了\");\r\n    $el.find(\"@empty\").when(() => visibleTodos().length === 0);\r\n\r\n    $el.find(\"@list\").repeat(visibleTodos, {\r\n      key: (todo) => todo.id,\r\n      tpl: \"@todo-tpl\",\r\n      render: ($row, todo) => {\r\n        $row.find(\"@title\").text(todo.title);\r\n        $row.find(\"@check\").prop(\"checked\", todo.done);\r\n\r\n        $row.find(\"@check\").on(\"change\", function () {\r\n          setDone(todo.id, this.checked);\r\n        });\r\n        $row.find(\"@del\").click(() => {\r\n          todos((list) => list.filter((item) => item.id !== todo.id));\r\n        });\r\n\r\n        $row.selected(() => todo.done);\r\n      },\r\n    });\r\n  }\r\n\r\n  $$.component(\"ex-todo\", ($el) => {\r\n    todo($el);\r\n    showSample(\"todo-source\", \"todo\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // コード比較のタブ切り替え（bridgey / jQuery）。\r\n  // 横に並べると1行が短くなって読みにくいので、切り替えて全幅で見せる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"code-tabs\", ($el) => {\r\n    const current = $$.state($el.find(\"@code-tab\").first().data(\"tab\") || \"bridgey\");\r\n\r\n    $el.find(\"@code-tab\").each((tab) => {\r\n      const name = tab.dataset.tab;\r\n\r\n      $$(tab)\r\n        .click(() => current(name))\r\n        .selected(() => current() === name);\r\n    });\r\n\r\n    $el.find(\"@code-pane\").each((pane) => {\r\n      $$(pane).when(() => current() === pane.dataset.tab);\r\n    });\r\n  });\r\n\r\n  // --- 目次のスクロール追従 ---\r\n  function initTOC() {\r\n    // 目次の追従は「あると嬉しい」機能。使えない環境でも描画を止めない。\r\n    // （1つの API が無いだけでページ全体が死ぬ、を自分でやらないため）\r\n    if (typeof IntersectionObserver === \"undefined\") return;\r\n    const toc = document.querySelector(\".toc\");\r\n    if (!toc) return;\r\n    const links = [...toc.querySelectorAll(\"a[href^='#']\")];\r\n    const map = new Map();\r\n    links.forEach((a) => {\r\n      const el = document.getElementById(a.getAttribute(\"href\").slice(1));\r\n      if (el) map.set(el, a);\r\n    });\r\n    tocObserver = new IntersectionObserver(\r\n      (entries) => {\r\n        entries.forEach((e) => {\r\n          if (!e.isIntersecting) return;\r\n          links.forEach((l) => l.classList.remove(\"active\"));\r\n          const a = map.get(e.target);\r\n          if (a) a.classList.add(\"active\");\r\n        });\r\n      },\r\n      { rootMargin: \"-72px 0px -70% 0px\", threshold: 0 }\r\n    );\r\n    map.forEach((_, el) => tocObserver.observe(el));\r\n  }\r\n})();","html":"<div class=\"card\" data-component=\"home-demo\">\n        <div class=\"demo-row\">\n          <span>数量</span>\n          <span class=\"demo-qty\">\n            <button data-brg=\"dec\" aria-label=\"減らす\">−</button>\n            <b data-brg=\"qty\"></b>\n            <button data-brg=\"inc\" aria-label=\"増やす\">＋</button>\n          </span>\n        </div>\n        <div class=\"demo-row\">\n          <span>合計</span>\n          <span class=\"demo-price\"><span data-brg=\"total\"></span><small>円</small></span>\n        </div>\n        <p class=\"demo-free\" data-brg=\"free\">3個以上で送料無料になりました</p>\n        <div class=\"demo-bar\" data-brg=\"bar\"><i></i></div>\n      </div>"},"counter":{"js":"const MAX_QUANTITY = 20;\r\n    const UNIT_PRICE = 1100;\r\n\r\n    // 状態はこの1つだけ\r\n    const quantity = $$.state(1);\r\n\r\n    // ここから下は全部「導出」。どこにも代入していない\r\n    const doubled = $$.computed(() => quantity() * 2);\r\n    const total = $$.computed(() => quantity() * UNIT_PRICE);\r\n    const isBulk = $$.computed(() => quantity() >= 10);\r\n    const isMax = $$.computed(() => quantity() >= MAX_QUANTITY);\r\n\r\n    $el.find(\"@cnt-n\").text(quantity);\r\n    $el.find(\"@cnt-doubled\").text(doubled);\r\n    $el.find(\"@cnt-total\").text(total, $$.money);\r\n\r\n    $el.find(\"@cnt-inc\").click(() => {\r\n      quantity((current) => Math.min(MAX_QUANTITY, current + 1));\r\n    });\r\n    $el.find(\"@cnt-dec\").click(() => {\r\n      quantity((current) => Math.max(1, current - 1));\r\n    });\r\n    $el.find(\"@cnt-reset\").click(() => quantity(1));\r\n\r\n    $el.find(\"@cnt-inc\").disabled(isMax);\r\n    $el.find(\"@cnt-dec\").disabled(() => quantity() <= 1);\r\n    $el.find(\"@cnt-over\").when(isBulk);\r\n    $el.find(\"@cnt-limit\").when(isMax);\r\n  }\r\n\r\n  $$.component(\"ex-counter\", ($el) => {\r\n    counter($el);\r\n    showSample(\"counter-source\", \"counter\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: ToDo（一覧の状態管理）\r\n  // 一覧は repeat が描くので、行の DOM が使い回される＝入力途中の文字が消えない。\r\n  // ---------------------------------------------------------------------------\r\n  function todo($el) {\r\n    let nextId = 3;\r\n\r\n    const todos = $$.state([\r\n      { id: 1, title: \"見積書を送る\", done: false },\r\n      { id: 2, title: \"請求書を確認する\", done: true },\r\n    ]);\r\n\r\n    const filter = $el.find(\"@filter\").group();\r\n    const draft = $el.find(\"@input\").state(\"\");\r\n\r\n    // 表示する一覧は「絞り込んだ結果」を導出する\r\n    const visibleTodos = $$.computed(() => {\r\n      if (filter() === \"open\") return todos().filter((todo) => !todo.done);\r\n      if (filter() === \"done\") return todos().filter((todo) => todo.done);\r\n\r\n      return todos();\r\n    });\r\n\r\n    const remainingCount = $$.computed(() => {\r\n      return todos().filter((todo) => !todo.done).length;\r\n    });\r\n\r\n    const addTodo = () => {\r\n      const title = draft().trim();\r\n      if (!title) return;\r\n\r\n      todos((list) => [...list, { id: nextId++, title, done: false }]);\r\n      draft(\"\");\r\n    };\r\n\r\n    const setDone = (id, done) => {\r\n      todos((list) =>\r\n        list.map((todo) => {\r\n          if (todo.id !== id) return todo;\r\n\r\n          return { ...todo, done };\r\n        })\r\n      );\r\n    };\r\n\r\n    $el.find(\"@add\").click(addTodo);\r\n    $el.find(\"@input\").on(\"keydown\", (event) => {\r\n      if (event.key !== \"Enter\") return;\r\n\r\n      event.preventDefault();\r\n      addTodo();\r\n    });\r\n\r\n    $el.find(\"@counts\").text(remainingCount, \"件が未完了\");\r\n    $el.find(\"@empty\").when(() => visibleTodos().length === 0);\r\n\r\n    $el.find(\"@list\").repeat(visibleTodos, {\r\n      key: (todo) => todo.id,\r\n      tpl: \"@todo-tpl\",\r\n      render: ($row, todo) => {\r\n        $row.find(\"@title\").text(todo.title);\r\n        $row.find(\"@check\").prop(\"checked\", todo.done);\r\n\r\n        $row.find(\"@check\").on(\"change\", function () {\r\n          setDone(todo.id, this.checked);\r\n        });\r\n        $row.find(\"@del\").click(() => {\r\n          todos((list) => list.filter((item) => item.id !== todo.id));\r\n        });\r\n\r\n        $row.selected(() => todo.done);\r\n      },\r\n    });\r\n  }\r\n\r\n  $$.component(\"ex-todo\", ($el) => {\r\n    todo($el);\r\n    showSample(\"todo-source\", \"todo\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // コード比較のタブ切り替え（bridgey / jQuery）。\r\n  // 横に並べると1行が短くなって読みにくいので、切り替えて全幅で見せる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"code-tabs\", ($el) => {\r\n    const current = $$.state($el.find(\"@code-tab\").first().data(\"tab\") || \"bridgey\");\r\n\r\n    $el.find(\"@code-tab\").each((tab) => {\r\n      const name = tab.dataset.tab;\r\n\r\n      $$(tab)\r\n        .click(() => current(name))\r\n        .selected(() => current() === name);\r\n    });\r\n\r\n    $el.find(\"@code-pane\").each((pane) => {\r\n      $$(pane).when(() => current() === pane.dataset.tab);\r\n    });\r\n  });\r\n\r\n  // --- 目次のスクロール追従 ---\r\n  function initTOC() {\r\n    // 目次の追従は「あると嬉しい」機能。使えない環境でも描画を止めない。\r\n    // （1つの API が無いだけでページ全体が死ぬ、を自分でやらないため）\r\n    if (typeof IntersectionObserver === \"undefined\") return;\r\n    const toc = document.querySelector(\".toc\");\r\n    if (!toc) return;\r\n    const links = [...toc.querySelectorAll(\"a[href^='#']\")];\r\n    const map = new Map();\r\n    links.forEach((a) => {\r\n      const el = document.getElementById(a.getAttribute(\"href\").slice(1));\r\n      if (el) map.set(el, a);\r\n    });\r\n    tocObserver = new IntersectionObserver(\r\n      (entries) => {\r\n        entries.forEach((e) => {\r\n          if (!e.isIntersecting) return;\r\n          links.forEach((l) => l.classList.remove(\"active\"));\r\n          const a = map.get(e.target);\r\n          if (a) a.classList.add(\"active\");\r\n        });\r\n      },\r\n      { rootMargin: \"-72px 0px -70% 0px\", threshold: 0 }\r\n    );\r\n    map.forEach((_, el) => tocObserver.observe(el));\r\n  }\r\n})();","html":"<div class=\"card\" data-component=\"ex-counter\">\n          <div class=\"ex-total\" style=\"border:0;padding-top:0\">\n            <span>数量</span>\n            <span class=\"demo-qty\" style=\"display:inline-flex;align-items:center;gap:14px\">\n              <button type=\"button\" data-brg=\"cnt-dec\">−</button>\n              <b data-brg=\"cnt-n\" style=\"min-width:2em;text-align:center;font-size:20px\"></b>\n              <button type=\"button\" data-brg=\"cnt-inc\">＋</button>\n            </span>\n          </div>\n          <div class=\"ex-total\"><span>2倍した値</span><span data-brg=\"cnt-doubled\"></span></div>\n          <div class=\"ex-total\"><span>合計（単価 1,100円）</span>\n            <strong class=\"ex-price\"><span data-brg=\"cnt-total\"></span><small>円</small></strong></div>\n          <p class=\"good\" data-brg=\"cnt-over\">10個以上のまとめ買いです</p>\n          <p class=\"ex-hidden-note\" data-brg=\"cnt-limit\">上限は20個です</p>\n          <div class=\"ex-inline\">\n            <button type=\"button\" class=\"btn ghost\" data-brg=\"cnt-reset\" style=\"font-size:13px\">リセット</button>\n          </div>\n        </div>"},"exampleForm":{"js":"const options = $$.state(OPTIONS.slice());\r\n    const plan = $el.find(\"@plan\").group();\r\n\r\n    // オプション一覧（行の DOM は使い回されるのでチェックが消えない）\r\n    $el.find(\"@opts\").repeat(options, {\r\n      key: (option) => option.id,\r\n      tpl: \"@opt-tpl\",\r\n      render: ($row, option) => {\r\n        $row.find(\"@opt-name\").text(option.name);\r\n        $row.find(\"@opt-price\").text(option.price, $$.money, \"円/月\");\r\n        $row.find(\"@opt-check\").attr(\"value\", option.id);\r\n      },\r\n    });\r\n\r\n    // 選択を1つの state にして、合計は導出する（代入する場所を作らない）\r\n    // 後からオプションが増えても、この state に自動で参加する（張り直しは要らない）\r\n    const selectedIds = $el.find(\"@opt-check\").group();\r\n\r\n    const optionTotal = $$.computed(() => {\r\n      const priceOf = new Map(options().map((option) => [option.id, option.price]));\r\n\r\n      return selectedIds().reduce((sum, id) => sum + (priceOf.get(id) ?? 0), 0);\r\n    });\r\n\r\n    $el.find(\"@opt-total\").text(optionTotal, $$.money);\r\n\r\n    // 法人のときだけ会社名を表示し、同じ条件で必須にする\r\n    const isCorporate = $$.computed(() => plan() === \"corp\");\r\n    $el.find(\"@corp-box\").when(isCorporate);\r\n\r\n    const signupForm = $el.find(\"@form\").form({\r\n      company: {\r\n        required: isCorporate,\r\n        message: \"会社名を入力してください\",\r\n      },\r\n      tel: {\r\n        pattern: /^0\\d{9,10}$/,\r\n        message: \"電話番号の形式が正しくありません（ハイフンなし）\",\r\n      },\r\n      confirm: {\r\n        same: \"password\",\r\n        message: \"パスワードが一致しません\",\r\n      },\r\n      agree: {\r\n        required: true,\r\n        message: \"規約への同意が必要です\",\r\n      },\r\n      // promo は required だが画面に出ていない → 検証されない（CV を守る）\r\n    });\r\n\r\n    // 郵便番号の自動整形（日本語変換中は書き戻さないので変換が壊れない）\r\n    const zipCode = $el.find(\"#ex-zip\").state(\"\");\r\n\r\n    $el.find(\"#ex-zip\").val(() => {\r\n      const digits = String(zipCode()).replace(/[^0-9]/g, \"\").slice(0, 7);\r\n\r\n      return digits.length > 3\r\n        ? `${digits.slice(0, 3)}-${digits.slice(3)}`\r\n        : digits;\r\n    });\r\n\r\n    $el.find(\"@err-summary\").text(signupForm.errorCount, (count) => {\r\n      return count ? `未入力・不備が${count}件あります` : \"\";\r\n    });\r\n    $el.find(\"@submit\").disabled(signupForm.submitting);\r\n    $el.find(\"@done\").when(() => {\r\n      return signupForm.submitted() && signupForm.valid() && !signupForm.submitting();\r\n    });\r\n\r\n    return { form: signupForm, options };\r\n  }\r\n\r\n  $$.component(\"ex-form\", ($el) => {\r\n    const api = exampleForm($el);\r\n    showSample(\"ex-source\", \"exampleForm\");\r\n\r\n    api.form.submit(async () => {\r\n      // 送信の代わりに待つだけ。待っている間は submit ボタンが自動で無効になる\r\n      await new Promise((r) => setTimeout(r, 900));\r\n    });\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: 構造依存の事故を、その場で起こしてみせる。\r\n  //\r\n  // 左は「隣の要素を掴む」書き方（jQuery の .next() 相当）。\r\n  // 右は「名前で引く」書き方。HTML を1段ラップすると、左だけが黙って動かなくなる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"ex-structure\", ($el) => {\r\n    // 従来のやり方: nextElementSibling で隣を掴む\r\n    const oldHead = $el.find(\"@old-head\").el;\r\n\r\n    $$(oldHead).click(() => {\r\n      const body = oldHead.nextElementSibling;\r\n\r\n      if (!body || body.dataset.brg !== \"old-body\") {\r\n        // ここが事故。掴めていないのに例外は出ないので、誰も気づけない\r\n        $el.find(\"@old-log\").text(\"開きません。隣に別の要素が入りました（例外は出ません）\");\r\n        return;\r\n      }\r\n      const hidden = body.style.display === \"none\";\r\n      body.style.display = hidden ? \"\" : \"none\";\r\n      $el.find(\"@old-log\").text(hidden ? \"開きました\" : \"閉じました\");\r\n    });\r\n\r\n    // bridgey: 名前で引くので、構造が変わっても同じ要素に届く\r\n    const open = $$.state(true);\r\n\r\n    $el.find(\"@new-head\").click(() => open((v) => !v)).expanded(open);\r\n    $el.find(\"@new-body\").when(open);\r\n    $el.find(\"@new-log\").text(open, (v) => (v ? \"開きました\" : \"閉じました\"));\r\n\r\n    $el.find(\"@wrap\").click(function () {\r\n      for (const name of [\"old-body\", \"new-body\"]) {\r\n        const target = $el.find(`@${name}`).el;\r\n        if (!target || target.parentElement.dataset.wrapper) continue;\r\n\r\n        const wrapper = document.createElement(\"div\");\r\n        wrapper.dataset.wrapper = \"1\";\r\n        target.parentElement.insertBefore(wrapper, target);\r\n        wrapper.appendChild(target);\r\n      }\r\n      this.disabled = true;\r\n      $el.find(\"@old-log\").text(\"1段ラップしました。開いてみてください。\");\r\n      $el.find(\"@new-log\").text(\"1段ラップしました。開いてみてください。\");\r\n    });\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: エラーの隔離。\r\n  // わざと初期化に失敗する部品を混ぜても、他の部品は動き続ける。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"ex-broken\", () => {\r\n    // 元コードの s.offset().top と同じ状況（存在しない要素を触る）\r\n    const missing = document.querySelector(\"#this-element-does-not-exist\");\r\n    return void missing.getBoundingClientRect();\r\n  });\r\n\r\n  $$.component(\"ex-tabs\", ($el) => {\r\n    const current = $$.state(\"a\");\r\n\r\n    $el.find(\"@tab\").each((tab) => {\r\n      $$(tab).click(() => current(tab.dataset.tab)).selected(() => current() === tab.dataset.tab);\r\n    });\r\n    $el.find(\"@pane\").each((pane) => {\r\n      $$(pane).when(() => current() === pane.dataset.tab);\r\n    });\r\n  });\r\n\r\n  $$.component(\"ex-mini\", ($el) => {\r\n    const n = $$.state(5);\r\n\r\n    $el.find(\"@mini-n\").text(n);\r\n    $el.find(\"@mini-inc\").click(() => n((v) => v + 1));\r\n    $el.find(\"@mini-dec\").click(() => n((v) => v - 1));\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: CSS に無いクラス名を検出する。\r\n  // 警告の出口（$$.warnSink）を一時的に借りて、出た文を画面にも見せる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"ex-typo\", ($el) => {\r\n    $el.find(\"@run\").click(function () {\r\n      const original = $$.warnSink;\r\n      let captured = \"\";\r\n\r\n      $$.warnSink = (message) => {\r\n        captured += (captured ? \"\\n\\n\" : \"\") + message;\r\n        original(message);\r\n      };\r\n      try {\r\n        // \".ex-active\" のつもりで綴りを間違えている\r\n        $el.find(\"@run\").toggleClass(\"ex-actve\", $$.state(true));\r\n      } finally {\r\n        $$.warnSink = original;\r\n      }\r\n\r\n      this.disabled = true;\r\n      $el.find(\"@typo-log\").text(\r\n        captured || \"（この警告は1度だけ出ます。ページを読み込み直すとまた出ます）\"\r\n      );\r\n    });\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: カート。金額を全部「導出」する例。\r\n  // 代入している行が1つもないので、数量変更・削除・クーポンで合計がズレようがない。\r\n  // ---------------------------------------------------------------------------\r\n  const CART_ITEMS = [\r\n    { id: \"desk\", name: \"昇降デスク\", unit: 23800, qty: 1 },\r\n    { id: \"arm\", name: \"モニターアーム\", unit: 3300, qty: 1 },\r\n    { id: \"cable\", name: \"USB-C ケーブル\", unit: 1650, qty: 2 },\r\n  ];\r\n\r\n  function cart($el) {\r\n    const FREE_SHIPPING_FROM = 30000;\r\n    const SHIPPING_FEE = 550;\r\n    const TAX_RATE = 0.1;\r\n    const COUPON_RATE = 0.1;\r\n\r\n    const items = $$.state(CART_ITEMS.map((item) => ({ ...item })));\r\n    const useCoupon = $el.find(\"@coupon\").state(false);\r\n\r\n    // ここから下は全部「導出」。金額に代入している行は1つもない\r\n    const subtotal = $$.computed(() => {\r\n      return items().reduce((sum, item) => sum + item.unit * item.qty, 0);\r\n    });\r\n\r\n    const shipping = $$.computed(() => {\r\n      if (subtotal() === 0) return 0;\r\n\r\n      return subtotal() >= FREE_SHIPPING_FROM ? 0 : SHIPPING_FEE;\r\n    });\r\n\r\n    const discount = $$.computed(() => {\r\n      return useCoupon() ? Math.floor(subtotal() * COUPON_RATE) : 0;\r\n    });\r\n\r\n    const taxable = $$.computed(() => subtotal() - discount() + shipping());\r\n    const tax = $$.computed(() => Math.floor(taxable() * TAX_RATE));\r\n    const total = $$.computed(() => taxable() + tax());\r\n    const amountToFreeShipping = $$.computed(() => {\r\n      return Math.max(0, FREE_SHIPPING_FROM - subtotal());\r\n    });\r\n\r\n    const changeQuantity = (id, change) => {\r\n      items((list) =>\r\n        list.map((item) => {\r\n          if (item.id !== id) return item;\r\n\r\n          return { ...item, qty: Math.max(1, change(item.qty)) };\r\n        })\r\n      );\r\n    };\r\n\r\n    const removeItem = (id) => {\r\n      items((list) => list.filter((item) => item.id !== id));\r\n    };\r\n\r\n    $el.find(\"@rows\").repeat(items, {\r\n      key: (item) => item.id,\r\n      tpl: \"@row-tpl\",\r\n      render: ($row, item) => {\r\n        $row.find(\"@name\").text(item.name);\r\n        $row.find(\"@unit\").text(item.unit, $$.money, \"円\");\r\n        $row.find(\"@qty\").text(item.qty);\r\n        $row.find(\"@line\").text(item.unit * item.qty, $$.money, \"円\");\r\n\r\n        $row.find(\"@inc\").click(() => changeQuantity(item.id, (qty) => qty + 1));\r\n        $row.find(\"@dec\").click(() => changeQuantity(item.id, (qty) => qty - 1));\r\n        $row.find(\"@del\").click(() => removeItem(item.id));\r\n      },\r\n    });\r\n\r\n    const isEmpty = $$.computed(() => items().length === 0);\r\n\r\n    $el.find(\"@empty\").when(isEmpty);\r\n    $el.find(\"@summary\").when(() => !isEmpty());\r\n    $el.find(\"@subtotal\").text(subtotal, $$.money, \"円\");\r\n    $el.find(\"@ship\").text(shipping, (fee) => {\r\n      return fee === 0 ? \"無料\" : `${$$.money(fee)}円`;\r\n    });\r\n    $el.find(\"@discount\").text(discount, (amount) => {\r\n      return amount === 0 ? \"—\" : `-${$$.money(amount)}円`;\r\n    });\r\n    $el.find(\"@tax\").text(tax, $$.money, \"円\");\r\n    $el.find(\"@total\").text(total, $$.money);\r\n    $el.find(\"@to-free\").text(amountToFreeShipping, $$.money);\r\n    $el.find(\"@free-note\").when(() => {\r\n      return amountToFreeShipping() > 0 && !isEmpty();\r\n    });\r\n\r\n    $el.find(\"@restore\").click(() => {\r\n      items(CART_ITEMS.map((item) => ({ ...item })));\r\n    });\r\n  }\r\n\r\n  $$.component(\"ex-cart\", ($el) => {\r\n    cart($el);\r\n    showSample(\"cart-source\", \"cart\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: カウンター（最小の状態管理）\r\n  // 状態は n ひとつ。表示は全部そこから導出する。\r\n  // ---------------------------------------------------------------------------\r\n  function counter($el) {\r\n    const MAX_QUANTITY = 20;\r\n    const UNIT_PRICE = 1100;\r\n\r\n    // 状態はこの1つだけ\r\n    const quantity = $$.state(1);\r\n\r\n    // ここから下は全部「導出」。どこにも代入していない\r\n    const doubled = $$.computed(() => quantity() * 2);\r\n    const total = $$.computed(() => quantity() * UNIT_PRICE);\r\n    const isBulk = $$.computed(() => quantity() >= 10);\r\n    const isMax = $$.computed(() => quantity() >= MAX_QUANTITY);\r\n\r\n    $el.find(\"@cnt-n\").text(quantity);\r\n    $el.find(\"@cnt-doubled\").text(doubled);\r\n    $el.find(\"@cnt-total\").text(total, $$.money);\r\n\r\n    $el.find(\"@cnt-inc\").click(() => {\r\n      quantity((current) => Math.min(MAX_QUANTITY, current + 1));\r\n    });\r\n    $el.find(\"@cnt-dec\").click(() => {\r\n      quantity((current) => Math.max(1, current - 1));\r\n    });\r\n    $el.find(\"@cnt-reset\").click(() => quantity(1));\r\n\r\n    $el.find(\"@cnt-inc\").disabled(isMax);\r\n    $el.find(\"@cnt-dec\").disabled(() => quantity() <= 1);\r\n    $el.find(\"@cnt-over\").when(isBulk);\r\n    $el.find(\"@cnt-limit\").when(isMax);\r\n  }\r\n\r\n  $$.component(\"ex-counter\", ($el) => {\r\n    counter($el);\r\n    showSample(\"counter-source\", \"counter\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: ToDo（一覧の状態管理）\r\n  // 一覧は repeat が描くので、行の DOM が使い回される＝入力途中の文字が消えない。\r\n  // ---------------------------------------------------------------------------\r\n  function todo($el) {\r\n    let nextId = 3;\r\n\r\n    const todos = $$.state([\r\n      { id: 1, title: \"見積書を送る\", done: false },\r\n      { id: 2, title: \"請求書を確認する\", done: true },\r\n    ]);\r\n\r\n    const filter = $el.find(\"@filter\").group();\r\n    const draft = $el.find(\"@input\").state(\"\");\r\n\r\n    // 表示する一覧は「絞り込んだ結果」を導出する\r\n    const visibleTodos = $$.computed(() => {\r\n      if (filter() === \"open\") return todos().filter((todo) => !todo.done);\r\n      if (filter() === \"done\") return todos().filter((todo) => todo.done);\r\n\r\n      return todos();\r\n    });\r\n\r\n    const remainingCount = $$.computed(() => {\r\n      return todos().filter((todo) => !todo.done).length;\r\n    });\r\n\r\n    const addTodo = () => {\r\n      const title = draft().trim();\r\n      if (!title) return;\r\n\r\n      todos((list) => [...list, { id: nextId++, title, done: false }]);\r\n      draft(\"\");\r\n    };\r\n\r\n    const setDone = (id, done) => {\r\n      todos((list) =>\r\n        list.map((todo) => {\r\n          if (todo.id !== id) return todo;\r\n\r\n          return { ...todo, done };\r\n        })\r\n      );\r\n    };\r\n\r\n    $el.find(\"@add\").click(addTodo);\r\n    $el.find(\"@input\").on(\"keydown\", (event) => {\r\n      if (event.key !== \"Enter\") return;\r\n\r\n      event.preventDefault();\r\n      addTodo();\r\n    });\r\n\r\n    $el.find(\"@counts\").text(remainingCount, \"件が未完了\");\r\n    $el.find(\"@empty\").when(() => visibleTodos().length === 0);\r\n\r\n    $el.find(\"@list\").repeat(visibleTodos, {\r\n      key: (todo) => todo.id,\r\n      tpl: \"@todo-tpl\",\r\n      render: ($row, todo) => {\r\n        $row.find(\"@title\").text(todo.title);\r\n        $row.find(\"@check\").prop(\"checked\", todo.done);\r\n\r\n        $row.find(\"@check\").on(\"change\", function () {\r\n          setDone(todo.id, this.checked);\r\n        });\r\n        $row.find(\"@del\").click(() => {\r\n          todos((list) => list.filter((item) => item.id !== todo.id));\r\n        });\r\n\r\n        $row.selected(() => todo.done);\r\n      },\r\n    });\r\n  }\r\n\r\n  $$.component(\"ex-todo\", ($el) => {\r\n    todo($el);\r\n    showSample(\"todo-source\", \"todo\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // コード比較のタブ切り替え（bridgey / jQuery）。\r\n  // 横に並べると1行が短くなって読みにくいので、切り替えて全幅で見せる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"code-tabs\", ($el) => {\r\n    const current = $$.state($el.find(\"@code-tab\").first().data(\"tab\") || \"bridgey\");\r\n\r\n    $el.find(\"@code-tab\").each((tab) => {\r\n      const name = tab.dataset.tab;\r\n\r\n      $$(tab)\r\n        .click(() => current(name))\r\n        .selected(() => current() === name);\r\n    });\r\n\r\n    $el.find(\"@code-pane\").each((pane) => {\r\n      $$(pane).when(() => current() === pane.dataset.tab);\r\n    });\r\n  });\r\n\r\n  // --- 目次のスクロール追従 ---\r\n  function initTOC() {\r\n    // 目次の追従は「あると嬉しい」機能。使えない環境でも描画を止めない。\r\n    // （1つの API が無いだけでページ全体が死ぬ、を自分でやらないため）\r\n    if (typeof IntersectionObserver === \"undefined\") return;\r\n    const toc = document.querySelector(\".toc\");\r\n    if (!toc) return;\r\n    const links = [...toc.querySelectorAll(\"a[href^='#']\")];\r\n    const map = new Map();\r\n    links.forEach((a) => {\r\n      const el = document.getElementById(a.getAttribute(\"href\").slice(1));\r\n      if (el) map.set(el, a);\r\n    });\r\n    tocObserver = new IntersectionObserver(\r\n      (entries) => {\r\n        entries.forEach((e) => {\r\n          if (!e.isIntersecting) return;\r\n          links.forEach((l) => l.classList.remove(\"active\"));\r\n          const a = map.get(e.target);\r\n          if (a) a.classList.add(\"active\");\r\n        });\r\n      },\r\n      { rootMargin: \"-72px 0px -70% 0px\", threshold: 0 }\r\n    );\r\n    map.forEach((_, el) => tocObserver.observe(el));\r\n  }\r\n})();","html":"<div class=\"card\" data-component=\"ex-form\">\n        <form class=\"ex-form\" data-brg=\"form\">\n          <div class=\"ex-row\">\n            <label>お申し込み種別</label>\n            <div class=\"ex-inline\">\n              <label><input type=\"radio\" name=\"plan\" value=\"personal\" data-brg=\"plan\" checked> 個人</label>\n              <label><input type=\"radio\" name=\"plan\" value=\"corp\" data-brg=\"plan\"> 法人</label>\n            </div>\n          </div>\n\n          <div class=\"ex-row\" data-brg=\"corp-box\">\n            <label for=\"ex-company\">会社名（法人のときだけ必須）</label>\n            <input id=\"ex-company\" name=\"company\" type=\"text\" autocomplete=\"organization\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-mail\">メールアドレス（必須）</label>\n            <input id=\"ex-mail\" name=\"mail\" type=\"email\" required autocomplete=\"email\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-tel\">電話番号（必須・ハイフンなし）</label>\n            <input id=\"ex-tel\" name=\"tel\" type=\"tel\" required autocomplete=\"tel\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-zip\">郵便番号（入力すると自動でハイフンが入ります）</label>\n            <input id=\"ex-zip\" name=\"zip\" type=\"text\" autocomplete=\"postal-code\" placeholder=\"1000001\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-pass\">パスワード（8文字以上）</label>\n            <input id=\"ex-pass\" name=\"password\" type=\"password\" minlength=\"8\">\n          </div>\n          <div class=\"ex-row\">\n            <label for=\"ex-pass2\">パスワード（確認）</label>\n            <input id=\"ex-pass2\" name=\"confirm\" type=\"password\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label>オプション</label>\n            <ul class=\"ex-opts\" data-brg=\"opts\"></ul>\n            <template data-brg=\"opt-tpl\">\n              <li data-brg=\"opt-row\">\n                <input type=\"checkbox\" data-brg=\"opt-check\">\n                <span data-brg=\"opt-name\" style=\"flex:1\"></span>\n                <span data-brg=\"opt-price\" class=\"ex-hidden-note\"></span>\n              </li>\n            </template>\n          </div>\n\n          <!-- 画面に出ていない必須項目。旧来のやり方だとここで CV が死ぬ -->\n          <div data-brg=\"hidden-box\" style=\"display:none\">\n            <label for=\"ex-promo\">キャンペーンコード（画面に出ていない必須項目）</label>\n            <input id=\"ex-promo\" name=\"promo\" type=\"text\" required>\n          </div>\n\n          <div class=\"ex-inline\">\n            <label><input type=\"checkbox\" name=\"agree\" data-brg=\"agree\" required> 規約に同意する（必須）</label>\n          </div>\n\n          <div class=\"ex-total\">\n            <span>オプション合計</span>\n            <strong class=\"ex-price\"><span data-brg=\"opt-total\">0</span><small>円/月</small></strong>\n          </div>\n\n          <div class=\"ex-total\" style=\"border:0\">\n            <span class=\"bad\" data-brg=\"err-summary\"></span>\n            <button type=\"submit\" class=\"btn primary\" data-brg=\"submit\">この内容で申し込む</button>\n          </div>\n          <p class=\"good\" data-brg=\"done\">送信しました</p>\n        </form>\n      </div>"},"cart":{"js":"const FREE_SHIPPING_FROM = 30000;\r\n    const SHIPPING_FEE = 550;\r\n    const TAX_RATE = 0.1;\r\n    const COUPON_RATE = 0.1;\r\n\r\n    const items = $$.state(CART_ITEMS.map((item) => ({ ...item })));\r\n    const useCoupon = $el.find(\"@coupon\").state(false);\r\n\r\n    // ここから下は全部「導出」。金額に代入している行は1つもない\r\n    const subtotal = $$.computed(() => {\r\n      return items().reduce((sum, item) => sum + item.unit * item.qty, 0);\r\n    });\r\n\r\n    const shipping = $$.computed(() => {\r\n      if (subtotal() === 0) return 0;\r\n\r\n      return subtotal() >= FREE_SHIPPING_FROM ? 0 : SHIPPING_FEE;\r\n    });\r\n\r\n    const discount = $$.computed(() => {\r\n      return useCoupon() ? Math.floor(subtotal() * COUPON_RATE) : 0;\r\n    });\r\n\r\n    const taxable = $$.computed(() => subtotal() - discount() + shipping());\r\n    const tax = $$.computed(() => Math.floor(taxable() * TAX_RATE));\r\n    const total = $$.computed(() => taxable() + tax());\r\n    const amountToFreeShipping = $$.computed(() => {\r\n      return Math.max(0, FREE_SHIPPING_FROM - subtotal());\r\n    });\r\n\r\n    const changeQuantity = (id, change) => {\r\n      items((list) =>\r\n        list.map((item) => {\r\n          if (item.id !== id) return item;\r\n\r\n          return { ...item, qty: Math.max(1, change(item.qty)) };\r\n        })\r\n      );\r\n    };\r\n\r\n    const removeItem = (id) => {\r\n      items((list) => list.filter((item) => item.id !== id));\r\n    };\r\n\r\n    $el.find(\"@rows\").repeat(items, {\r\n      key: (item) => item.id,\r\n      tpl: \"@row-tpl\",\r\n      render: ($row, item) => {\r\n        $row.find(\"@name\").text(item.name);\r\n        $row.find(\"@unit\").text(item.unit, $$.money, \"円\");\r\n        $row.find(\"@qty\").text(item.qty);\r\n        $row.find(\"@line\").text(item.unit * item.qty, $$.money, \"円\");\r\n\r\n        $row.find(\"@inc\").click(() => changeQuantity(item.id, (qty) => qty + 1));\r\n        $row.find(\"@dec\").click(() => changeQuantity(item.id, (qty) => qty - 1));\r\n        $row.find(\"@del\").click(() => removeItem(item.id));\r\n      },\r\n    });\r\n\r\n    const isEmpty = $$.computed(() => items().length === 0);\r\n\r\n    $el.find(\"@empty\").when(isEmpty);\r\n    $el.find(\"@summary\").when(() => !isEmpty());\r\n    $el.find(\"@subtotal\").text(subtotal, $$.money, \"円\");\r\n    $el.find(\"@ship\").text(shipping, (fee) => {\r\n      return fee === 0 ? \"無料\" : `${$$.money(fee)}円`;\r\n    });\r\n    $el.find(\"@discount\").text(discount, (amount) => {\r\n      return amount === 0 ? \"—\" : `-${$$.money(amount)}円`;\r\n    });\r\n    $el.find(\"@tax\").text(tax, $$.money, \"円\");\r\n    $el.find(\"@total\").text(total, $$.money);\r\n    $el.find(\"@to-free\").text(amountToFreeShipping, $$.money);\r\n    $el.find(\"@free-note\").when(() => {\r\n      return amountToFreeShipping() > 0 && !isEmpty();\r\n    });\r\n\r\n    $el.find(\"@restore\").click(() => {\r\n      items(CART_ITEMS.map((item) => ({ ...item })));\r\n    });\r\n  }\r\n\r\n  $$.component(\"ex-cart\", ($el) => {\r\n    cart($el);\r\n    showSample(\"cart-source\", \"cart\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: カウンター（最小の状態管理）\r\n  // 状態は n ひとつ。表示は全部そこから導出する。\r\n  // ---------------------------------------------------------------------------\r\n  function counter($el) {\r\n    const MAX_QUANTITY = 20;\r\n    const UNIT_PRICE = 1100;\r\n\r\n    // 状態はこの1つだけ\r\n    const quantity = $$.state(1);\r\n\r\n    // ここから下は全部「導出」。どこにも代入していない\r\n    const doubled = $$.computed(() => quantity() * 2);\r\n    const total = $$.computed(() => quantity() * UNIT_PRICE);\r\n    const isBulk = $$.computed(() => quantity() >= 10);\r\n    const isMax = $$.computed(() => quantity() >= MAX_QUANTITY);\r\n\r\n    $el.find(\"@cnt-n\").text(quantity);\r\n    $el.find(\"@cnt-doubled\").text(doubled);\r\n    $el.find(\"@cnt-total\").text(total, $$.money);\r\n\r\n    $el.find(\"@cnt-inc\").click(() => {\r\n      quantity((current) => Math.min(MAX_QUANTITY, current + 1));\r\n    });\r\n    $el.find(\"@cnt-dec\").click(() => {\r\n      quantity((current) => Math.max(1, current - 1));\r\n    });\r\n    $el.find(\"@cnt-reset\").click(() => quantity(1));\r\n\r\n    $el.find(\"@cnt-inc\").disabled(isMax);\r\n    $el.find(\"@cnt-dec\").disabled(() => quantity() <= 1);\r\n    $el.find(\"@cnt-over\").when(isBulk);\r\n    $el.find(\"@cnt-limit\").when(isMax);\r\n  }\r\n\r\n  $$.component(\"ex-counter\", ($el) => {\r\n    counter($el);\r\n    showSample(\"counter-source\", \"counter\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // examples: ToDo（一覧の状態管理）\r\n  // 一覧は repeat が描くので、行の DOM が使い回される＝入力途中の文字が消えない。\r\n  // ---------------------------------------------------------------------------\r\n  function todo($el) {\r\n    let nextId = 3;\r\n\r\n    const todos = $$.state([\r\n      { id: 1, title: \"見積書を送る\", done: false },\r\n      { id: 2, title: \"請求書を確認する\", done: true },\r\n    ]);\r\n\r\n    const filter = $el.find(\"@filter\").group();\r\n    const draft = $el.find(\"@input\").state(\"\");\r\n\r\n    // 表示する一覧は「絞り込んだ結果」を導出する\r\n    const visibleTodos = $$.computed(() => {\r\n      if (filter() === \"open\") return todos().filter((todo) => !todo.done);\r\n      if (filter() === \"done\") return todos().filter((todo) => todo.done);\r\n\r\n      return todos();\r\n    });\r\n\r\n    const remainingCount = $$.computed(() => {\r\n      return todos().filter((todo) => !todo.done).length;\r\n    });\r\n\r\n    const addTodo = () => {\r\n      const title = draft().trim();\r\n      if (!title) return;\r\n\r\n      todos((list) => [...list, { id: nextId++, title, done: false }]);\r\n      draft(\"\");\r\n    };\r\n\r\n    const setDone = (id, done) => {\r\n      todos((list) =>\r\n        list.map((todo) => {\r\n          if (todo.id !== id) return todo;\r\n\r\n          return { ...todo, done };\r\n        })\r\n      );\r\n    };\r\n\r\n    $el.find(\"@add\").click(addTodo);\r\n    $el.find(\"@input\").on(\"keydown\", (event) => {\r\n      if (event.key !== \"Enter\") return;\r\n\r\n      event.preventDefault();\r\n      addTodo();\r\n    });\r\n\r\n    $el.find(\"@counts\").text(remainingCount, \"件が未完了\");\r\n    $el.find(\"@empty\").when(() => visibleTodos().length === 0);\r\n\r\n    $el.find(\"@list\").repeat(visibleTodos, {\r\n      key: (todo) => todo.id,\r\n      tpl: \"@todo-tpl\",\r\n      render: ($row, todo) => {\r\n        $row.find(\"@title\").text(todo.title);\r\n        $row.find(\"@check\").prop(\"checked\", todo.done);\r\n\r\n        $row.find(\"@check\").on(\"change\", function () {\r\n          setDone(todo.id, this.checked);\r\n        });\r\n        $row.find(\"@del\").click(() => {\r\n          todos((list) => list.filter((item) => item.id !== todo.id));\r\n        });\r\n\r\n        $row.selected(() => todo.done);\r\n      },\r\n    });\r\n  }\r\n\r\n  $$.component(\"ex-todo\", ($el) => {\r\n    todo($el);\r\n    showSample(\"todo-source\", \"todo\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // コード比較のタブ切り替え（bridgey / jQuery）。\r\n  // 横に並べると1行が短くなって読みにくいので、切り替えて全幅で見せる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"code-tabs\", ($el) => {\r\n    const current = $$.state($el.find(\"@code-tab\").first().data(\"tab\") || \"bridgey\");\r\n\r\n    $el.find(\"@code-tab\").each((tab) => {\r\n      const name = tab.dataset.tab;\r\n\r\n      $$(tab)\r\n        .click(() => current(name))\r\n        .selected(() => current() === name);\r\n    });\r\n\r\n    $el.find(\"@code-pane\").each((pane) => {\r\n      $$(pane).when(() => current() === pane.dataset.tab);\r\n    });\r\n  });\r\n\r\n  // --- 目次のスクロール追従 ---\r\n  function initTOC() {\r\n    // 目次の追従は「あると嬉しい」機能。使えない環境でも描画を止めない。\r\n    // （1つの API が無いだけでページ全体が死ぬ、を自分でやらないため）\r\n    if (typeof IntersectionObserver === \"undefined\") return;\r\n    const toc = document.querySelector(\".toc\");\r\n    if (!toc) return;\r\n    const links = [...toc.querySelectorAll(\"a[href^='#']\")];\r\n    const map = new Map();\r\n    links.forEach((a) => {\r\n      const el = document.getElementById(a.getAttribute(\"href\").slice(1));\r\n      if (el) map.set(el, a);\r\n    });\r\n    tocObserver = new IntersectionObserver(\r\n      (entries) => {\r\n        entries.forEach((e) => {\r\n          if (!e.isIntersecting) return;\r\n          links.forEach((l) => l.classList.remove(\"active\"));\r\n          const a = map.get(e.target);\r\n          if (a) a.classList.add(\"active\");\r\n        });\r\n      },\r\n      { rootMargin: \"-72px 0px -70% 0px\", threshold: 0 }\r\n    );\r\n    map.forEach((_, el) => tocObserver.observe(el));\r\n  }\r\n})();","html":"<div class=\"card\" data-component=\"ex-cart\">\n        <ul class=\"ex-opts\" data-brg=\"rows\" style=\"gap:2px\"></ul>\n        <template data-brg=\"row-tpl\">\n          <li data-brg=\"row\" style=\"gap:12px\">\n            <span data-brg=\"name\" style=\"flex:1\"></span>\n            <span class=\"ex-hidden-note\" data-brg=\"unit\"></span>\n            <span style=\"display:inline-flex;align-items:center;gap:8px\">\n              <button type=\"button\" data-brg=\"dec\" aria-label=\"減らす\">−</button>\n              <b data-brg=\"qty\" style=\"min-width:1.6em;text-align:center\"></b>\n              <button type=\"button\" data-brg=\"inc\" aria-label=\"増やす\">＋</button>\n            </span>\n            <span data-brg=\"line\" style=\"min-width:5.5em;text-align:right\"></span>\n            <button type=\"button\" data-brg=\"del\" aria-label=\"削除\">×</button>\n          </li>\n        </template>\n\n        <p data-brg=\"empty\" style=\"text-align:center;color:var(--muted);padding:18px 0\">\n          カートは空です\n        </p>\n\n        <div data-brg=\"summary\">\n          <div class=\"ex-total\"><span>小計</span><span data-brg=\"subtotal\"></span></div>\n          <div class=\"ex-total\"><span data-brg=\"ship-label\">送料</span><span data-brg=\"ship\"></span></div>\n          <div class=\"ex-total\"><span>クーポン</span><span data-brg=\"discount\"></span></div>\n          <div class=\"ex-total\"><span>消費税（10%）</span><span data-brg=\"tax\"></span></div>\n          <div class=\"ex-total\" style=\"border-top:2px solid var(--line)\">\n            <b>合計</b>\n            <strong class=\"ex-price\"><span data-brg=\"total\"></span><small>円</small></strong>\n          </div>\n        </div>\n\n        <div class=\"ex-inline\" style=\"margin-top:14px\">\n          <label><input type=\"checkbox\" data-brg=\"coupon\"> クーポンを使う（10% OFF）</label>\n          <button type=\"button\" class=\"btn ghost\" data-brg=\"restore\" style=\"font-size:13px\">商品を戻す</button>\n        </div>\n        <p class=\"ex-hidden-note\" data-brg=\"free-note\">"},"todo":{"js":"let nextId = 3;\r\n\r\n    const todos = $$.state([\r\n      { id: 1, title: \"見積書を送る\", done: false },\r\n      { id: 2, title: \"請求書を確認する\", done: true },\r\n    ]);\r\n\r\n    const filter = $el.find(\"@filter\").group();\r\n    const draft = $el.find(\"@input\").state(\"\");\r\n\r\n    // 表示する一覧は「絞り込んだ結果」を導出する\r\n    const visibleTodos = $$.computed(() => {\r\n      if (filter() === \"open\") return todos().filter((todo) => !todo.done);\r\n      if (filter() === \"done\") return todos().filter((todo) => todo.done);\r\n\r\n      return todos();\r\n    });\r\n\r\n    const remainingCount = $$.computed(() => {\r\n      return todos().filter((todo) => !todo.done).length;\r\n    });\r\n\r\n    const addTodo = () => {\r\n      const title = draft().trim();\r\n      if (!title) return;\r\n\r\n      todos((list) => [...list, { id: nextId++, title, done: false }]);\r\n      draft(\"\");\r\n    };\r\n\r\n    const setDone = (id, done) => {\r\n      todos((list) =>\r\n        list.map((todo) => {\r\n          if (todo.id !== id) return todo;\r\n\r\n          return { ...todo, done };\r\n        })\r\n      );\r\n    };\r\n\r\n    $el.find(\"@add\").click(addTodo);\r\n    $el.find(\"@input\").on(\"keydown\", (event) => {\r\n      if (event.key !== \"Enter\") return;\r\n\r\n      event.preventDefault();\r\n      addTodo();\r\n    });\r\n\r\n    $el.find(\"@counts\").text(remainingCount, \"件が未完了\");\r\n    $el.find(\"@empty\").when(() => visibleTodos().length === 0);\r\n\r\n    $el.find(\"@list\").repeat(visibleTodos, {\r\n      key: (todo) => todo.id,\r\n      tpl: \"@todo-tpl\",\r\n      render: ($row, todo) => {\r\n        $row.find(\"@title\").text(todo.title);\r\n        $row.find(\"@check\").prop(\"checked\", todo.done);\r\n\r\n        $row.find(\"@check\").on(\"change\", function () {\r\n          setDone(todo.id, this.checked);\r\n        });\r\n        $row.find(\"@del\").click(() => {\r\n          todos((list) => list.filter((item) => item.id !== todo.id));\r\n        });\r\n\r\n        $row.selected(() => todo.done);\r\n      },\r\n    });\r\n  }\r\n\r\n  $$.component(\"ex-todo\", ($el) => {\r\n    todo($el);\r\n    showSample(\"todo-source\", \"todo\");\r\n  });\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // コード比較のタブ切り替え（bridgey / jQuery）。\r\n  // 横に並べると1行が短くなって読みにくいので、切り替えて全幅で見せる。\r\n  // ---------------------------------------------------------------------------\r\n  $$.component(\"code-tabs\", ($el) => {\r\n    const current = $$.state($el.find(\"@code-tab\").first().data(\"tab\") || \"bridgey\");\r\n\r\n    $el.find(\"@code-tab\").each((tab) => {\r\n      const name = tab.dataset.tab;\r\n\r\n      $$(tab)\r\n        .click(() => current(name))\r\n        .selected(() => current() === name);\r\n    });\r\n\r\n    $el.find(\"@code-pane\").each((pane) => {\r\n      $$(pane).when(() => current() === pane.dataset.tab);\r\n    });\r\n  });\r\n\r\n  // --- 目次のスクロール追従 ---\r\n  function initTOC() {\r\n    // 目次の追従は「あると嬉しい」機能。使えない環境でも描画を止めない。\r\n    // （1つの API が無いだけでページ全体が死ぬ、を自分でやらないため）\r\n    if (typeof IntersectionObserver === \"undefined\") return;\r\n    const toc = document.querySelector(\".toc\");\r\n    if (!toc) return;\r\n    const links = [...toc.querySelectorAll(\"a[href^='#']\")];\r\n    const map = new Map();\r\n    links.forEach((a) => {\r\n      const el = document.getElementById(a.getAttribute(\"href\").slice(1));\r\n      if (el) map.set(el, a);\r\n    });\r\n    tocObserver = new IntersectionObserver(\r\n      (entries) => {\r\n        entries.forEach((e) => {\r\n          if (!e.isIntersecting) return;\r\n          links.forEach((l) => l.classList.remove(\"active\"));\r\n          const a = map.get(e.target);\r\n          if (a) a.classList.add(\"active\");\r\n        });\r\n      },\r\n      { rootMargin: \"-72px 0px -70% 0px\", threshold: 0 }\r\n    );\r\n    map.forEach((_, el) => tocObserver.observe(el));\r\n  }\r\n})();","html":"<div class=\"card\" data-component=\"ex-todo\">\n        <div class=\"ex-inline\" style=\"gap:8px\">\n          <input type=\"text\" data-brg=\"input\" placeholder=\"やることを入力して Enter\"\n                 style=\"flex:1;min-width:12em;padding:9px 11px;border:1px solid var(--line);border-radius:8px;background:transparent;color:inherit;font:inherit\">\n          <button type=\"button\" class=\"btn primary\" data-brg=\"add\" style=\"font-size:13px\">追加</button>\n        </div>\n\n        <div class=\"ex-inline\" style=\"margin-top:12px\">\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"all\" data-brg=\"filter\" checked> すべて</label>\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"open\" data-brg=\"filter\"> 未完了</label>\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"done\" data-brg=\"filter\"> 完了</label>\n          <span class=\"ex-hidden-note\" data-brg=\"counts\"></span>\n        </div>\n\n        <ul class=\"ex-opts\" data-brg=\"list\" style=\"margin-top:10px\"></ul>\n        <template data-brg=\"todo-tpl\">\n          <li data-brg=\"item\">\n            <input type=\"checkbox\" data-brg=\"check\">\n            <span data-brg=\"title\" style=\"flex:1\"></span>\n            <input type=\"text\" data-brg=\"memo\" placeholder=\"メモ\"\n                   style=\"width:9em;padding:5px 8px;border:1px solid var(--line);border-radius:6px;background:transparent;color:inherit;font:inherit;font-size:12px\">\n            <button type=\"button\" data-brg=\"del\">×</button>\n          </li>\n        </template>\n\n        <p data-brg=\"empty\" style=\"text-align:center;color:var(--muted);padding:14px 0\">該当するものがありません</p>"}};
